package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.identity.IdentityService;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.transaction.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;

/** Actual short writer/CAS/append-only receipt, with fictional native runtime states. */
@EnabledIfEnvironmentVariable(named="B45_MYSQL",matches="true")
class OwnerJobCancelMySqlTest {
    OwnerJobsReadMySqlTest f;JdbcOwnerJobCancellation store;OwnerJobCancelService service;PlatformTransactionManager tx;
    final String key="fictional-key!punctuation";
    @BeforeEach void setup(){f=new OwnerJobsReadMySqlTest();f.setup();f.f.save(f.f.generic());f.f.f.f.jdbc.execute("ALTER TABLE jobs ADD result_hash BINARY(32)");store=new JdbcOwnerJobCancellation(f.f.f.f.source);tx=new DataSourceTransactionManager(f.f.f.f.source);service=service(tx);}
    OwnerJobCancelService service(PlatformTransactionManager manager){return new OwnerJobCancelService(new SharedWriteExecutor(new JdbcSharedWriteEntry(f.f.f.f.source),manager),store,Clock.fixed(f.f.cutoff.plusSeconds(10),ZoneOffset.UTC));}
    JdbcOwnerJobCancellation.Cancelled cancel(String request){return service.cancel(f.owner,f.f.root,0,"Fictional cancellation",request);}
    @Test void originalUnsentRootCancelsWithOneCasAndReceiptAndNoBudgetReset(){f.f.f.f.jdbc.update("UPDATE jobs SET state='queued' WHERE id=?",f.f.root);var result=cancel(key);assertEquals("cancelled",result.state());assertEquals(1,result.revision());assertEquals(0,f.f.f.f.jdbc.queryForObject("SELECT call_count FROM jobs WHERE id=?",Integer.class,f.f.root));assertEquals(result,cancel(key));assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='job_cancel'",Integer.class));assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT revision FROM jobs WHERE id=?",Integer.class,f.f.root));}
    @Test void runningCancellationRecordsRequestWithoutTouchingSlotAttemptsOrBudget(){f.f.f.writer.execute(s->{new JdbcJobRecords(f.f.f.f.source).prepareAttempt(new JdbcJobRecords.Attempt("fictional-running-attempt",f.f.root,1,"{}",f.f.root,com.lianxibu.site.domain.protocol.CanonicalJson.hash(com.lianxibu.site.domain.protocol.CanonicalJson.Domain.INPUT,f.f.body)),f.f.cutoff);return true;});f.f.f.f.jdbc.update("UPDATE jobs SET state='running',call_count=1 WHERE id=?",f.f.root);f.f.f.f.jdbc.update("UPDATE jobs SET state='running' WHERE id='fictional-running-attempt'");f.f.f.f.jdbc.update("UPDATE worker_lock SET slot_state='occupied',slot_revision=9,job_id='fictional-running-attempt'");var result=cancel(key);assertEquals("cancel_requested",result.state());assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT call_count FROM jobs WHERE id=?",Integer.class,f.f.root));assertEquals("running",f.f.f.f.jdbc.queryForObject("SELECT state FROM jobs WHERE id='fictional-running-attempt'",String.class));assertEquals("occupied",f.f.f.f.jdbc.queryForObject("SELECT slot_state FROM worker_lock",String.class));assertEquals(9,f.f.f.f.jdbc.queryForObject("SELECT slot_revision FROM worker_lock",Integer.class));}
    @Test void originalKeyReplaySurvivesCurrentRevisionChangeButRebindingIsRejected(){var result=cancel(key);f.f.f.f.jdbc.update("UPDATE jobs SET revision=7,state='superseded' WHERE id=?",f.f.root);assertEquals(result,cancel(key));for(Runnable invalid:List.<Runnable>of(()->service.cancel(f.owner,f.f.root,1,"Fictional cancellation",key),()->service.cancel(f.owner,f.f.root,0,"Changed fictional reason",key),()->service.cancel(new IdentityService.Actor("fictional-other-owner","owner"),f.f.root,0,"Fictional cancellation",key)))assertEquals("identity_conflict",assertThrows(JdbcOwnerJobCancellation.Rejected.class,invalid::run).getMessage());}
    @Test void staleRevisionUnknownResultOrWrongRoleCannotCancel(){assertEquals("revision_conflict",assertThrows(JdbcOwnerJobCancellation.Rejected.class,()->service.cancel(f.owner,f.f.root,1,"Fictional cancellation",key)).getMessage());for(String state:List.of("unknown_external","succeeded","failed","result_conflict","superseded")){f.f.f.f.jdbc.update("UPDATE jobs SET state=? WHERE id=?",state,f.f.root);assertEquals("run_frozen",assertThrows(JdbcOwnerJobCancellation.Rejected.class,()->cancel(key)).getMessage());}f.f.f.f.jdbc.update("UPDATE jobs SET state='queued',result_hash=? WHERE id=?",new byte[32],f.f.root);assertThrows(JdbcOwnerJobCancellation.Rejected.class,()->cancel(key));assertThrows(JdbcOwnerJobCancellation.Rejected.class,()->service.cancel(f.owner,f.f.intent,0,"Fictional cancellation",key));assertThrows(IdentityService.Rejected.class,()->service.cancel(new IdentityService.Actor("fictional-member","member"),f.f.root,0,"Fictional cancellation",key));assertEquals(0,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='job_cancel'",Integer.class));}
    @Test void appendFailureRollsBackRootAndActualLostCommitAcknowledgementReplaysOriginal(){f.f.f.f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_cancel_receipt_refused CHECK (COALESCE(target_type,'')<>'job_cancel')");assertThrows(RuntimeException.class,()->cancel(key));assertEquals(0,f.f.f.f.jdbc.queryForObject("SELECT revision FROM jobs WHERE id=?",Integer.class,f.f.root));f.f.f.f.jdbc.execute("ALTER TABLE jobs DROP CHECK fictional_cancel_receipt_refused");var uncertain=new PlatformTransactionManager(){boolean once=true;public TransactionStatus getTransaction(TransactionDefinition definition){return tx.getTransaction(definition);}public void rollback(TransactionStatus status){tx.rollback(status);}public void commit(TransactionStatus status){boolean writer=!org.springframework.transaction.support.TransactionSynchronizationManager.isCurrentTransactionReadOnly();tx.commit(status);if(writer&&once){once=false;throw new TransactionSystemException("Fictional lost commit acknowledgement");}}};var result=service(uncertain).cancel(f.owner,f.f.root,0,"Fictional cancellation",key);assertEquals(result,cancel(key));assertEquals(1,result.revision());assertEquals(1,f.f.f.f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='job_cancel'",Integer.class));}
    @Test void damagedNativeReceiptAndCallerTransactionCannotServeReplay(){cancel(key);f.f.f.f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='job_cancel'",new byte[32]);assertEquals("identity_conflict",assertThrows(JdbcOwnerJobCancellation.Rejected.class,()->cancel(key)).getMessage());assertThrows(RuntimeException.class,()->f.f.f.writer.execute(s->cancel("fictional-second")));}
}
